from .errors import VersionError


def parse(v):
    """'1.2.3' -> (1, 2, 3). Exactly three dot-separated non-negative integers without signs or spaces,
    else VersionError."""
    parts = v.split(".")
    if len(parts) != 3 or not all(p.isdigit() for p in parts):
        raise VersionError(v)
    return tuple(int(p) for p in parts)


def compare(a, b):
    """-1, 0 or 1 as version string a is lower than, equal to or higher than b (numeric, not text, order)."""
    x, y = parse(a), parse(b)
    return (x > y) - (x < y)


def bump(v, part):
    """Increment 'major', 'minor' or 'patch' of v, zeroing the parts after it; other part names: VersionError."""
    major, minor, patch = parse(v)
    if part == "major":
        return f"{major + 1}.0.0"
    if part == "minor":
        return f"{major}.{minor + 1}.0"
    if part == "patch":
        return f"{major}.{minor}.{patch + 1}"
    raise VersionError(part)
